#pragma once
const char UI_PAGE[]=R"HTML(<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meine Lüftung</title><style>body{font:17px system-ui;background:#f2f5f7;color:#172b3a;max-width:800px;margin:auto;padding:20px}section{background:white;border-radius:16px;padding:22px;margin:18px 0}button,input,select{font:inherit;padding:12px;border:1px solid #b5c4cd;border-radius:8px;max-width:100%;box-sizing:border-box}button{background:#176958;color:white;cursor:pointer;margin:6px 0}label{display:block;margin:12px 0}input,select{display:block;width:100%;margin-top:6px}code{overflow-wrap:anywhere}#message{position:sticky;top:0;background:#e3f3eb;padding:14px;white-space:pre-wrap}small{color:#4c6372}h1{margin-bottom:0}.danger{background:#a03838}</style><h1>Meine Lüftung</h1><p>Ambientika · ein Lüfter · lokale Steuerung</p><div id="message" role="status" aria-live="polite">Verbindung wird geprüft …</div>
<section><h2>1 · Heim-WLAN verbinden</h2><p>Ein 2,4-GHz-WLAN verwenden. Nach dem Speichern bleibt diese Seite zunächst erreichbar.</p><form id="wifi"><label>WLAN-Name<input name="ssid" maxlength="32" required autocomplete="off"></label><label>WLAN-Passwort<input name="password" type="password" maxlength="63" autocomplete="new-password"></label><button>WLAN verbinden</button></form><p id="network"></p><small>Einrichtungs-WLAN: Passwort <b>Lueftung-Start</b>. Es schließt nach Verbindung oder spätestens nach 10 Minuten. Neustart öffnet es erneut.</small></section>
<section><h2>2 · Lüfter freigeben</h2><p>Vorher spannungsfrei verdrahten und den Lüfter auf „Master mit Wandpanel“ einstellen. Anleitung beachten.</p><p id="bus"></p><button id="enable">Verdrahtung geprüft – freigeben</button><button id="disable">Busausgabe sperren</button><p><small>Zum Anhalten zuerst „Aus“ wählen. Sperren beendet nur die Befehlsübertragung.</small></p></section>
<section><h2>3 · Lüftung bedienen</h2><p id="state">Noch kein Zustand verfügbar.</p><form id="control"><label>Betriebsart<select name="mode"><option value="wrg">Wärmerückgewinnung – Standard</option><option value="auto">Automatik mit Feuchtesensor</option><option value="boost">Boost – 20 Minuten Abluft</option><option value="supply">Dauerhafte Zuluft</option><option value="extract">Dauerhafte Abluft</option><option value="pause">Pause – Klappe offen</option><option value="off">Aus – Klappe geschlossen</option></select></label><label>Lüfterstufe<select name="level"><option value="1">1 – niedrig</option><option value="2">2 – mittel</option><option value="3">3 – hoch</option><option value="0">0 – gerätespezifische Stufe</option></select></label><label>Feuchtestufe für Automatik<select name="humidity"><option value="2">2</option><option value="3">3</option></select></label><label>Nachtbetrieb für Automatik<select name="night"><option value="0">Nein</option><option value="1">Ja</option></select></label><button>Übernehmen</button></form><button class="danger" id="off">Aus wählen</button><button id="query">Sensorstatus abfragen</button><p id="sensors">Noch keine bestätigte Antwort vom Lüfter.</p><small>Die Anzeige beschreibt gesendete Befehle, keine gemessene Motordrehzahl. Richtungswechsel enthalten mindestens 10 Sekunden Pause. Automatik und WRG wechseln alle 60 Sekunden die Richtung.</small></section>
<section><h2>4 · Mit Loxone verbinden</h2><p>Dem ESP im Router eine feste IP zuweisen. Als virtuellen HTTP-Ausgang verwenden:</p><label>Befehl<select id="loxmode"><option value="wrg&level=1">WRG Stufe 1</option><option value="auto&humidity=2&night=0">Automatik Tag</option><option value="auto&humidity=2&night=1">Automatik Nacht</option><option value="boost">Boost</option><option value="off">Aus</option></select></label><input id="url" readonly aria-label="Loxone Befehlsadresse"><button id="copy">Adresse kopieren</button><details><summary>API-Schlüssel und technische Hinweise</summary><p><code id="key"></code></p><p>Nur im vertrauenswürdigen Heimnetz verwenden. HTTP ist unverschlüsselt, diese lokale Seite zeigt den API-Schlüssel. Keine Internet-Portfreigabe einrichten.</p></details></section>
<script>
const key='{{KEY}}', $=s=>document.querySelector(s);let initialized=false;
$('#key').textContent=key;
const names={wrg:'Wärmerückgewinnung',auto:'Automatik',boost:'Boost',off:'Aus',pause:'Pause',supply:'Zuluft',extract:'Abluft',disabled:'Bus gesperrt'};
function message(s){$('#message').textContent=s}
async function command(path,params={}){let p=new URLSearchParams({...params,key});let r=await fetch(path+'?'+p,{method:'POST'});if(!r.ok)throw Error(await r.text());return r}
function bind(id,fn){$(id).onclick=async()=>{try{await fn();await refresh()}catch(e){message('Aktion fehlgeschlagen: '+e.message)}}}
$('#wifi').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));if(data.password.length>0&&data.password.length<8){message('Das WLAN-Passwort muss mindestens 8 Zeichen haben.');return}try{await command('/wifi',data);message('WLAN gespeichert. Verbindung wird aufgebaut. Bitte bis zu 60 Sekunden warten.')}catch(e){message(e.message)}};
$('#control').onsubmit=async e=>{e.preventDefault();try{await command('/api/control',Object.fromEntries(new FormData(e.target)));message('Betriebsart übernommen. Eine Motorpause vor dem Start ist normal.');await refresh()}catch(e){message(e.message)}};
bind('#enable',async()=>{await command('/enable',{enabled:1});message('Bus freigegeben. Jetzt WRG auf Stufe 1 wählen.')});
bind('#disable',async()=>{await command('/enable',{enabled:0});message('Busausgabe gesperrt.')});
bind('#off',async()=>{await command('/api/control',{mode:'off'});message('Aus beauftragt. Der ESP sendet spätestens nach 500 ms, bei laufender Statusabfrage nach deren Sendepause.')});
bind('#query',async()=>{await command('/api/query');message('Status angefordert. Drei Sekunden Sendepause abwarten.')});
function url(){ $('#url').value=location.origin+'/api/control?key='+key+'&mode='+$('#loxmode').value}$('#loxmode').onchange=url;url();
$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#url').value);message('Adresse kopiert.')}catch(e){$('#url').focus();$('#url').select();message('Adresse markiert – mit Strg+C oder dem Kopiermenü kopieren.')}};
async function refresh(){try{let r=await fetch('/api/status');if(!r.ok)throw Error('HTTP '+r.status);let s=await r.json();$('#bus').textContent=s.enabled?'Bus ist freigegeben.':'Bus ist gesperrt.';$('#state').textContent=(names[s.mode]||s.mode)+' · '+(names[s.phase]||s.phase)+' · Stufe '+s.level;$('#control button').disabled=!s.enabled;$('#enable').disabled=s.enabled;$('#disable').disabled=!s.enabled;$('#sensors').textContent=s.device_status_received?'Letzte Geräteantwort vor '+Math.floor(s.status_age_ms/1000)+' s · Feuchtealarm: '+(s.humidity_alarm?'aktiv':'inaktiv')+' · Filteralarm: '+((s.filter_1||s.filter_2)?'aktiv':'inaktiv'):'Noch keine bestätigte Geräteantwort. Statusabfrage starten.';if(!initialized){for(let f of ['mode','level','humidity','night']){let k=f==='humidity'?'humidity_level':f;$('#control [name="'+f+'"]').value=f==='night'?Number(s.night):s[k]}initialized=true;message('Steuerung erreichbar. Einrichtung von oben nach unten durchführen.')}let n=await(await fetch('/network')).json();$('#network').textContent=n.connected?'Heim-WLAN verbunden. Neue Adresse: http://'+n.ip+' – bitte notieren und im Heim-WLAN öffnen.':'Noch keine Heim-WLAN-Verbindung. WLAN-Name und Passwort prüfen.'}catch(e){message('Verbindung unterbrochen. Nach WLAN-Einrichtung zurück ins Heim-WLAN wechseln und die neue ESP-IP öffnen.')}}
refresh();setInterval(refresh,2500);
</script></html>)HTML";
